90	/// Minimal, strict DER decoder and the slice of X.509 needed by `inspect`.
91	mod x509 {
92	    use std::fmt::Write;
93	
94	    pub(super) struct Cert {
95	        pub(super) subject: String,
96	        pub(super) issuer: String,
97	        pub(super) serial_hex: String,
98	        pub(super) not_before: String,
99	        pub(super) not_after: String,
100	    }
101	
102	    #[derive(Clone, Copy)]
103	    struct Tlv<'a> {
104	        tag: u8,
105	        content: &'a [u8],
106	    }
107	
108	    const TAG_INTEGER: u8 = 0x02;
109	    const TAG_BIT_STRING: u8 = 0x03;
110	    const TAG_OCTET_STRING: u8 = 0x04;
111	    const TAG_BOOLEAN: u8 = 0x01;
112	    const TAG_OID: u8 = 0x06;
113	    const TAG_SEQUENCE: u8 = 0x30;
114	    const TAG_SET: u8 = 0x31;
115	    const TAG_UTC_TIME: u8 = 0x17;
116	    const TAG_GENERALIZED_TIME: u8 = 0x18;
117	
118	    /// Read exactly one DER TLV. Rejects indefinite length, non-minimal
119	    /// length encodings and truncated data.
120	    fn read_tlv(buf: &[u8]) -> Result<(Tlv<'_>, &[u8]), String> {
121	        let tag = *buf.first().ok_or_else(|| "unexpected end of data".to_string())?;
122	        if tag & 0x1F == 0x1F {
123	            return Err("multi-byte tags are not supported".to_string());
124	        }
125	        let first_len = *buf.get(1).ok_or_else(|| "truncated length".to_string())?;
126	        let (len, header_len) = match first_len {
127	            0x00..=0x7F => (first_len as usize, 2),
128	            0x80 => return Err("indefinite length is not valid DER".to_string()),
129	            0xFF => return Err("reserved length byte".to_string()),
130	            long => {
131	                let n = (long & 0x7F) as usize;
132	                if !(1..=4).contains(&n) {
133	                    return Err("length is too large".to_string());
134	                }
135	                let bytes = buf
136	                    .get(2..2 + n)
137	                    .ok_or_else(|| "truncated long length".to_string())?;
138	                if bytes[0] == 0 {
139	                    return Err("non-minimal length encoding".to_string());
140	                }
141	                let mut len = 0usize;
142	                for &b in bytes {
143	                    len = len
144	                        .checked_shl(8)
145	                        .and_then(|l| l.checked_add(b as usize))
146	                        .ok_or_else(|| "length overflow".to_string())?;
147	                }
148	                if len < 0x80 {
149	                    return Err("non-minimal length encoding".to_string());
150	                }
151	                (len, 2 + n)
152	            }
153	        };
154	        let total = header_len
155	            .checked_add(len)
156	            .filter(|&t| t <= buf.len())
157	            .ok_or_else(|| "truncated TLV content".to_string())?;
158	        Ok((
159	            Tlv {
160	                tag,
161	                content: &buf[header_len..total],
162	            },
163	            &buf[total..],
164	        ))
165	    }
166	
167	    fn read_tagged<'a>(
168	        buf: &'a [u8],
169	        tag: u8,
170	        what: &str,
171	    ) -> Result<(Tlv<'a>, &'a [u8]), String> {
172	        let (tlv, rest) = read_tlv(buf).map_err(|e| format!("{what}: {e}"))?;
173	        if tlv.tag != tag {
174	            return Err(format!("expected {what} (tag 0x{tag:02X}), got 0x{:02X}", tlv.tag));
175	        }
176	        Ok((tlv, rest))
177	    }
178	
179	    pub(super) fn parse(bytes: &[u8]) -> Result<Cert, String> {
180	        // Certificate ::= SEQUENCE { tbsCertificate, signatureAlgorithm,
181	        // signatureValue BIT STRING } — and nothing trailing.
182	        let (cert, rest) = read_tagged(bytes, TAG_SEQUENCE, "Certificate SEQUENCE")?;
183	        if !rest.is_empty() {
184	            return Err(format!("{} trailing byte(s) after certificate", rest.len()));
185	        }
186	
187	        let c = cert.content;
188	        let (tbs, c) = read_tagged(c, TAG_SEQUENCE, "tbsCertificate")?;
189	        let (_sig_alg, c) = read_tagged(c, TAG_SEQUENCE, "signatureAlgorithm")?;
190	        let (sig_value, c) = read_tlv(c)?;
191	        if sig_value.tag != TAG_BIT_STRING {
192	            return Err("signature must be a BIT STRING".to_string());
193	        }
194	        if sig_value.content.is_empty() || sig_value.content[0] > 7 {
195	            return Err("invalid signature BIT STRING".to_string());
196	        }
197	        if !c.is_empty() {
198	            return Err("trailing data in Certificate".to_string());
199	        }
200	
201	        // TBSCertificate ::= SEQUENCE {
202	        //   version [0] EXPLICIT Version DEFAULT v1, serialNumber, signature,
203	        //   issuer, validity, subject, subjectPublicKeyInfo, ... }
204	        let t = tbs.content;
205	        let (first, t2) = read_tlv(t)?;
206	        let (version, t) = if first.tag == 0xA0 {
207	            let (ver, vrest) = read_tagged(first.content, TAG_INTEGER, "version")?;
208	            if !vrest.is_empty() || ver.content.len() != 1 || ver.content[0] > 2 {
209	                return Err("invalid certificate version".to_string());
210	            }
211	            (ver.content[0], t2)
212	        } else {
213	            // No explicit version: v1 certificate.
214	            (0u8, t)
215	        };
216	
217	        let (serial, t3) = read_tagged(t, TAG_INTEGER, "serialNumber")?;
218	        let t = t3;
219	        let (_tbs_sig, t) = read_tagged(t, TAG_SEQUENCE, "tbs signatureAlgorithm")?;
220	        let (issuer, t) = read_tagged(t, TAG_SEQUENCE, "issuer")?;
221	        let (validity, t) = read_tagged(t, TAG_SEQUENCE, "validity")?;
222	        let (subject, t) = read_tagged(t, TAG_SEQUENCE, "subject")?;
223	        let (spki, t_after_spki) = read_tagged(t, TAG_SEQUENCE, "subjectPublicKeyInfo")?;
224	        check_spki(spki)?;
225	        // Optional tail of TBSCertificate, in a fixed order:
226	        //   issuerUniqueID  [1] IMPLICIT BIT STRING  (v2/v3, at most once)
227	        //   subjectUniqueID [2] IMPLICIT BIT STRING  (v2/v3, at most once)
228	        //   extensions      [3] EXPLICIT             (v3 only, at most once,
229	        //                                             and the last field)
230	        // Nothing else may follow subjectPublicKeyInfo: fields cannot be
231	        // skipped, reordered or dropped. The extensions interior is decoded in
232	        // full by `check_extensions`; the unique IDs carry BIT STRING content
233	        // directly (implicit tagging), validated by `check_bit_string`.
234	        let mut t = t_after_spki;
235	        let mut issuer_uid_seen = false;
236	        let mut subject_uid_seen = false;
237	        let mut extensions_present = false;
238	        while !t.is_empty() {
239	            let tag_hint = t.first().copied();
240	            let (field, rest) = read_tlv(t).map_err(|e| match tag_hint {
241	                Some(0x81) => format!("issuerUniqueID: {e}"),
242	                Some(0x82) => format!("subjectUniqueID: {e}"),
243	                // A truncated field whose tag is already readable can still
244	                // be located: tag 0xA3 is the extensions field.
245	                Some(0xA3) => format!("extensions field: {e}"),
246	                _ => e,
247	            })?;
248	            match field.tag {
249	                0x81 | 0x82 => {
250	                    let what = if field.tag == 0x81 {
251	                        "issuerUniqueID"
252	                    } else {
253	                        "subjectUniqueID"
254	                    };
255	                    if version < 1 {
256	                        return Err(format!(
257	                            "{what} is only allowed in v2 or v3 certificates, this is v1"
258	                        ));
259	                    }
260	                    if extensions_present {
261	                        return Err(format!(
262	                            "{what} must appear before the extensions field, \
263	                             which is the last field of tbsCertificate"
264	                        ));
265	                    }
266	                    if field.tag == 0x81 {
267	                        if issuer_uid_seen {
268	                            return Err("duplicate issuerUniqueID field".to_string());
269	                        }
270	                        if subject_uid_seen {
271	                            return Err(
272	                                "issuerUniqueID must appear before subjectUniqueID".to_string()
273	                            );
274	                        }
275	                        issuer_uid_seen = true;
276	                    } else if subject_uid_seen {
277	                        return Err("duplicate subjectUniqueID field".to_string());
278	                    } else {
279	                        subject_uid_seen = true;
280	                    }
281	                    check_bit_string(field.content, what)?;
282	                }
283	                0xA1 | 0xA2 => {
284	                    let what = if field.tag == 0xA1 {
285	                        "issuerUniqueID"
286	                    } else {
287	                        "subjectUniqueID"
288	                    };
289	                    return Err(format!(
290	                        "{what} must be an implicitly tagged primitive BIT STRING \
291	                         (tag 0x{:02X}); constructed tag 0x{:02X} is an explicit wrapper \
292	                         and is not allowed",
293	                        field.tag - 0x20,
294	                        field.tag
295	                    ));
296	                }
297	                0xA3 => {
298	                    if extensions_present {
299	                        return Err("duplicate extensions field".to_string());
300	                    }
301	                    if version != 2 {
302	                        let name = if version == 0 {
303	                            "v1"
304	                        } else {
305	                            "v2"
306	                        };
307	                        return Err(format!(
308	                            "extensions are only allowed in v3 certificates, this is {name}"
309	                        ));
310	                    }
311	                    check_extensions(field.content)?;
312	                    extensions_present = true;
313	                }
314	                other => {
315	                    return Err(format!(
316	                        "unexpected field after subjectPublicKeyInfo (tag 0x{other:02X}): \
317	                         only issuerUniqueID [1], subjectUniqueID [2] and extensions [3] \
318	                         are allowed there, and extensions must be last"
319	                    ));
320	                }
321	            }
322	            t = rest;
323	        }
324	
325	        let serial_hex = format_serial(serial.content)?;
326	        let issuer = format_name(issuer)?;
327	        let subject = format_name(subject)?;
328	
329	        let v = validity.content;
330	        let (nb, v2) = read_tlv(v)?;
331	        let (na, v3) = read_tlv(v2)?;
332	        if !v3.is_empty() {
333	            return Err("trailing data in validity".to_string());
334	        }
335	        let not_before = format_time(nb)?;
336	        let not_after = format_time(na)?;
337	
338	        Ok(Cert {
339	            subject,
340	            issuer,
341	            serial_hex,
342	            not_before,
343	            not_after,
344	        })
345	    }
346	
347	    /// Validate the content of the extensions field, i.e. the bytes wrapped
348	    /// by `[3] EXPLICIT`:
349	    ///
350	    /// ```text
351	    /// Extensions ::= SEQUENCE SIZE (1..MAX) OF Extension
352	    /// Extension  ::= SEQUENCE {
353	    ///   extnID    OBJECT IDENTIFIER,
354	    ///   critical  BOOLEAN DEFAULT FALSE,
355	    ///   extnValue OCTET STRING }
356	    /// ```
357	    ///
358	    /// The wrapper must contain exactly one non-empty Extensions SEQUENCE.
359	    /// Every extension must contain its OID and OCTET STRING in that order,
360	    /// with at most one (DER-encoded) BOOLEAN between them and nothing after.
361	    /// Extension contents are never interpreted: unknown but well-formed
362	    /// extension OIDs are accepted and `critical: TRUE` is not a failure.
363	    fn check_extensions(wrapper: &[u8]) -> Result<(), String> {
364	        let (list, rest) = read_tagged(wrapper, TAG_SEQUENCE, "extensions")?;
365	        if !rest.is_empty() {
366	            return Err("extensions wrapper contains data after the Extensions SEQUENCE".to_string());
367	        }
368	        if list.content.is_empty() {
369	            return Err("extensions SEQUENCE is empty".to_string());
370	        }
371	
372	        let mut buf = list.content;
373	        while !buf.is_empty() {
374	            let (ext, rest) = read_tagged(buf, TAG_SEQUENCE, "extension")?;
375	            buf = rest;
376	
377	            let (oid, after_oid) = read_tagged(ext.content, TAG_OID, "extension OID")?;
378	            parse_oid(oid.content).map_err(|e| format!("extension OID: {e}"))?;
379	
380	            // critical is optional; whatever stands between the OID and the
381	            // OCTET STRING must be exactly one BOOLEAN if it is present.
382	            let (maybe_bool, after_critical) = read_tlv(after_oid)
383	                .map_err(|e| format!("extension after OID: {e}"))?;
384	            let (octets, after_octets) = if maybe_bool.tag == TAG_BOOLEAN {
385	                match maybe_bool.content {
386	                    [0xFF] => {}
387	                    [0x00] => {
388	                        return Err(
389	                            "extension critical: explicit DER encoding of DEFAULT FALSE is not allowed"
390	                                .to_string()
391	                        )
392	                    }
393	                    _ => {
394	                        return Err(
395	                            "extension critical: invalid DER encoding of BOOLEAN".to_string()
396	                        )
397	                    }
398	                }
399	                read_tagged(after_critical, TAG_OCTET_STRING, "extension value")?
400	            } else {
401	                // Not a BOOLEAN: this element must itself be the extnValue.
402	                if maybe_bool.tag != TAG_OCTET_STRING {
403	                    return Err(format!(
404	                        "extension must contain a critical BOOLEAN then an OCTET STRING, \
405	                         got tag 0x{:02X}",
406	                        maybe_bool.tag
407	                    ));
408	                }
409	                (maybe_bool, after_critical)
410	            };
411	            // An empty OCTET STRING is legal; its bytes are not interpreted.
412	            let _ = octets.content;
413	            if !after_octets.is_empty() {
414	                return Err("trailing data in extension".to_string());
415	            }
416	        }
417	        Ok(())
418	    }
419	
420	    /// SubjectPublicKeyInfo ::= SEQUENCE {
421	    ///   algorithm        AlgorithmIdentifier,
422	    ///   subjectPublicKey BIT STRING }
423	    /// Nothing may be missing and no extra elements may follow.
424	    fn check_spki(spki: Tlv) -> Result<(), String> {
425	        let (alg, rest) = read_tagged(
426	            spki.content,
427	            TAG_SEQUENCE,
428	            "subjectPublicKeyInfo algorithm identifier",
429	        )?;
430	        check_algorithm_identifier(alg)?;
431	        let (key, rest) = read_tagged(rest, TAG_BIT_STRING, "subjectPublicKey")?;
432	        check_bit_string(key.content, "subjectPublicKey")?;
433	        if !rest.is_empty() {
434	            return Err("trailing data in subjectPublicKeyInfo".to_string());
435	        }
436	        Ok(())
437	    }
438	
439	    /// AlgorithmIdentifier ::= SEQUENCE {
440	    ///   algorithm  OBJECT IDENTIFIER,
441	    ///   parameters ANY DEFINED BY algorithm OPTIONAL }
442	    /// The parameters, if present, must be exactly one complete DER TLV;
443	    /// absent parameters and an explicit NULL are both accepted. The
444	    /// parameter content is not interpreted for any particular algorithm.
445	    fn check_algorithm_identifier(alg: Tlv) -> Result<(), String> {
446	        let (oid, rest) = read_tagged(alg.content, TAG_OID, "algorithm OID")?;
447	        parse_oid(oid.content).map_err(|e| format!("algorithm OID: {e}"))?;
448	        if rest.is_empty() {
449	            return Ok(());
450	        }
451	        let (_params, after) =
452	            read_tlv(rest).map_err(|e| format!("algorithm parameters: {e}"))?;
453	        if !after.is_empty() {
454	            return Err("multiple algorithm parameters".to_string());
455	        }
456	        Ok(())
457	    }
458	
459	    /// Validate the DER content of a BIT STRING: one leading byte counting
460	    /// unused bits (0..=7), and when the count is nonzero those low bits of
461	    /// the final data byte must all be zero. An empty bit string is only
462	    /// legal with a zero count.
463	    fn check_bit_string(content: &[u8], what: &str) -> Result<(), String> {
464	        let unused = *content
465	            .first()
466	            .ok_or_else(|| format!("{what} BIT STRING is missing the unused-bits byte"))?;
467	        if unused > 7 {
468	            return Err(format!("{what} BIT STRING has invalid unused-bits count {unused}"));
469	        }
470	        let data = &content[1..];
471	        if data.is_empty() {
472	            if unused != 0 {
473	                return Err(format!(
474	                    "{what} BIT STRING declares {unused} unused bits but has no data"
475	                ));
476	            }
477	            return Ok(());
478	        }
479	        if unused != 0 && data[data.len() - 1] & ((1u8 << unused) - 1) != 0 {
480	            return Err(format!(
481	                "{what} BIT STRING has set bits among the {unused} unused trailing bits"
482	            ));
483	        }
484	        Ok(())
485	    }
486	
487	    /// Render the serial number as upper-case hex, matching the integer value
488	    /// (a DER sign-padding 0x00 byte is not part of the number).
489	    fn format_serial(content: &[u8]) -> Result<String, String> {
490	        if content.is_empty() {
491	            return Err("empty serial number".to_string());
492	        }
493	        if content.len() > 1 && content[0] == 0xFF && content[1] & 0x80 == 0 {
494	            return Err("non-minimal serial number encoding".to_string());
495	        }
496	        if content.len() > 1 && content[0] == 0x00 && content[1] & 0x80 == 0 {
497	            return Err("non-minimal serial number encoding".to_string());
498	        }
499	        if content[0] & 0x80 != 0 && !(content.len() > 1 && content[0] == 0x00) {
500	            return Err("negative serial number".to_string());
501	        }
502	        let digits = if content.len() > 1 && content[0] == 0x00 {
503	            &content[1..]
504	        } else {
505	            content
506	        };
507	        let mut s = String::with_capacity(digits.len() * 2);
508	        for b in digits {
509	            write!(s, "{b:02X}").unwrap();
510	        }
511	        if s.is_empty() {
512	            s.push_str("00");
513	        }
514	        Ok(s)
515	    }
516	
517	    /// Name ::= SEQUENCE OF RDN; rendered per RFC 4514 (RDNs reversed,
518	    /// multi-valued RDNs joined with '+'). Values of known attribute types
519	    /// are emitted as real UTF-8 text (non-ASCII content preserved verbatim)
520	    /// when their tag has a text decoder; a known type carrying any other
521	    /// readable DER value (e.g. postalAddress as a SEQUENCE) keeps its short
522	    /// name and uses the '#' form carrying the value's full DER encoding in
523	    /// hex. Attributes without a known short name use their dotted OID with
524	    /// the same '#' form.
525	    fn format_name(name: Tlv) -> Result<String, String> {
526	        let mut rdn_buf = name.content;
527	        let mut rdns: Vec<String> = Vec::new();
528	        while !rdn_buf.is_empty() {
529	            let (set, rest) = read_tagged(rdn_buf, TAG_SET, "RelativeDistinguishedName")?;
530	            rdn_buf = rest;
531	
532	            let mut atv_buf = set.content;
533	            let mut parts = Vec::new();
534	            while !atv_buf.is_empty() {
535	                let (atv, rest) =
536	                    read_tagged(atv_buf, TAG_SEQUENCE, "AttributeTypeAndValue")?;
537	                atv_buf = rest;
538	
539	                let (oid, after_oid) = read_tagged(atv.content, TAG_OID, "attribute OID")?;
540	                let (value, after_value) = read_tlv(after_oid)?;
541	                if !after_value.is_empty() {
542	                    return Err("trailing data in attribute value".to_string());
543	                }
544	
545	                let oid_arcs = parse_oid(oid.content)?;
546	                match oid_short_name(&oid_arcs) {
547	                    Some(label) => {
548	                        if is_text_value_tag(value.tag) {
549	                            // Supported string type: decode to escaped text.
550	                            // A decode failure (e.g. invalid UTF-8) means the
551	                            // certificate is corrupt; it must not be salvaged
552	                            // by falling back to the hex form.
553	                            let text = decode_attribute_value(value.tag, value.content)?;
554	                            parts.push(format!("{label}={}", escape_value(&text)));
555	                        } else {
556	                            // Known type but a legal value with no text decoder
557	                            // (SEQUENCE, OCTET STRING, ...): keep the short name
558	                            // and show the full original DER encoding as '#'-hex.
559	                            parts.push(format!("{label}=#{}", value_hex(after_oid, after_value)));
560	                        }
561	                    }
562	                    None => {
563	                        // Unknown attribute type: RFC 4514 requires the form
564	                        // OID=#hex, where the hex is the full DER encoding
565	                        // (tag, length and content) of the attribute value.
566	                        // The value is still validated: a UTF8String must
567	                        // hold valid UTF-8 even when shown as hex.
568	                        if value.tag == 0x0C {
569	                            std::str::from_utf8(value.content)
570	                                .map_err(|_| "invalid UTF-8 in UTF8String".to_string())?;
571	                        }
572	                        let hex = value_hex(after_oid, after_value);
573	                        parts.push(format!("{}=#{hex}", arcs_to_string(&oid_arcs)));
574	                    }
575	                }
576	            }
577	            if parts.is_empty() {
578	                return Err("empty RelativeDistinguishedName".to_string());
579	            }
580	            rdns.push(parts.join("+"));
581	        }
582	        rdns.reverse();
583	        Ok(rdns.join(","))
584	    }
585	
586	    /// Uppercase hex of one complete value TLV, sliced straight from the
587	    /// input bytes (`around` ends at `rest`). The original tag and length
588	    /// bytes survive verbatim, including a legal long-form length; nothing is
589	    /// re-encoded and content alone is never emitted.
590	    fn value_hex(around: &[u8], rest: &[u8]) -> String {
591	        let tlv_len = around.len() - rest.len();
592	        let mut hex = String::with_capacity(tlv_len * 2);
593	        for b in &around[..tlv_len] {
594	            write!(hex, "{b:02X}").unwrap();
595	        }
596	        hex
597	    }
598	
599	    /// Tags whose attribute values have a direct text decoding in
600	    /// `decode_attribute_value`. Every other tag that `read_tlv` accepts is a
601	    /// legal non-text value for display purposes and is rendered as '#'-hex.
602	    fn is_text_value_tag(tag: u8) -> bool {
603	        matches!(
604	            tag,
605	            0x0C | 0x12 | 0x13 | 0x14 | 0x16 | 0x1A | 0x1B | 0x1C | 0x1E
606	        )
607	    }
608	
609	    fn parse_oid(content: &[u8]) -> Result<Vec<u64>, String> {
610	        if content.is_empty() {
611	            return Err("empty OID".to_string());
612	        }
613	        let mut arcs = Vec::new();
614	        // The first subidentifier encodes the first two arcs as
615	        // 40*first + second and is itself a base-128 quantity, so it can
616	        // span multiple content bytes (e.g. 2.999 encodes as 0x88 0x37).
617	        let mut i = 0;
618	        let first = read_oid_arc(content, &mut i)?;
619	        match first {
620	            0..=39 => {
621	                arcs.push(0);
622	                arcs.push(first);
623	            }
624	            40..=79 => {
625	                arcs.push(1);
626	                arcs.push(first - 40);
627	            }
628	            _ => {
629	                arcs.push(2);
630	                arcs.push(first - 80);
631	            }
632	        }
633	        while i < content.len() {
634	            arcs.push(read_oid_arc(content, &mut i)?);
635	        }
636	        Ok(arcs)
637	    }
638	
639	    /// Read one base-128 subidentifier starting at `*i`. Rejects trailing
640	    /// continuation bytes and non-minimal encodings.
641	    fn read_oid_arc(content: &[u8], i: &mut usize) -> Result<u64, String> {
642	        let start = *i;
643	        let mut value = 0u64;
644	        loop {
645	            let b = *content
646	                .get(*i)
647	                .ok_or_else(|| "truncated OID arc".to_string())?;
648	            value = value
649	                .checked_mul(128)
650	                .and_then(|v| v.checked_add((b & 0x7F) as u64))
651	                .ok_or_else(|| "OID arc overflow".to_string())?;
652	            *i += 1;
653	            if b & 0x80 == 0 {
654	                break;
655	            }
656	        }
657	        if *i - start > 1 && content[start] == 0x80 {
658	            return Err("non-minimal OID arc encoding".to_string());
659	        }
660	        Ok(value)
661	    }
662	
663	    fn arcs_to_string(arcs: &[u64]) -> String {
664	        arcs.iter()
665	            .map(u64::to_string)
666	            .collect::<Vec<_>>()
667	            .join(".")
668	    }
669	
670	    fn oid_short_name(arcs: &[u64]) -> Option<&'static str> {
671	        // X.520 / X.521 (2.5.4.*) and the commonly used LDAP/PKCS names.
672	        let name = match arcs {
673	            [2, 5, 4, 3] => "CN",
674	            [2, 5, 4, 4] => "SN",
675	            [2, 5, 4, 5] => "serialNumber",
676	            [2, 5, 4, 6] => "C",
677	            [2, 5, 4, 7] => "L",
678	            [2, 5, 4, 8] => "ST",
679	            [2, 5, 4, 9] => "STREET",
680	            [2, 5, 4, 10] => "O",
681	            [2, 5, 4, 11] => "OU",
682	            [2, 5, 4, 12] => "title",
683	            [2, 5, 4, 17] => "postalAddress",
684	            [2, 5, 4, 18] => "postalCode",
685	            [2, 5, 4, 20] => "telephoneNumber",
686	            [2, 5, 4, 42] => "givenName",
687	            [2, 5, 4, 43] => "initials",
688	            [2, 5, 4, 44] => "generationQualifier",
689	            [2, 5, 4, 46] => "dnQualifier",
690	            [2, 5, 4, 65] => "pseudonym",
691	            [0, 9, 2342, 19200300, 100, 1, 1] => "UID",
692	            [0, 9, 2342, 19200300, 100, 1, 25] => "DC",
693	            [1, 2, 840, 113549, 1, 9, 1] => "emailAddress",
694	            _ => return None,
695	        };
696	        Some(name)
697	    }
698	
699	    /// Decode a DirectoryString-style attribute value into UTF-8 text.
700	    fn decode_attribute_value(tag: u8, content: &[u8]) -> Result<String, String> {
701	        let s = match tag {
702	            0x0C => std::str::from_utf8(content)
703	                .map_err(|_| "invalid UTF-8 in UTF8String".to_string())?
704	                .to_string(),
705	            // ASCII-family strings: every byte is also its Unicode code point.
706	            0x12 | 0x13 | 0x16 | 0x1A => content.iter().map(|&b| b as char).collect(),
707	            // T.61 / GeneralString are conventionally treated as Latin-1 here.
708	            0x14 | 0x1B => content.iter().map(|&b| b as char).collect(),
709	            0x1E => {
710	                if content.len() % 2 != 0 {
711	                    return Err("odd-length BMPString".to_string());
712	                }
713	                let units: Vec<u16> = content
714	                    .chunks_exact(2)
715	                    .map(|c| u16::from_be_bytes([c[0], c[1]]))
716	                    .collect();
717	                char::decode_utf16(units.iter().copied())
718	                    .map(|r| r.map_err(|_| "unpaired surrogate in BMPString".to_string()))
719	                    .collect::<Result<String, _>>()?
720	            }
721	            0x1C => {
722	                if content.len() % 4 != 0 {
723	                    return Err("invalid UniversalString length".to_string());
724	                }
725	                let mut s = String::new();
726	                for c in content.chunks_exact(4) {
727	                    let cp = u32::from_be_bytes([c[0], c[1], c[2], c[3]]);
728	                    if (0xD800..=0xDFFF).contains(&cp) || cp > 0x10FFFF {
729	                        return Err("invalid code point in UniversalString".to_string());
730	                    }
731	                    s.push(char::from_u32(cp).unwrap());
732	                }
733	                s
734	            }
735	            _ => {
736	                return Err(format!(
737	                    "unsupported attribute value string type (tag 0x{tag:02X})"
738	                ))
739	            }
740	        };
741	        Ok(s)
742	    }
743	
744	    /// RFC 4514 value escaping; everything above the ASCII control range
745	    /// (including CJK text) passes through unchanged.
746	    fn escape_value(value: &str) -> String {
747	        let mut out = String::with_capacity(value.len());
748	        let last = value.chars().count().saturating_sub(1);
749	        for (i, c) in value.chars().enumerate() {
750	            let at_edge = i == 0 || i == last;
751	            let needs_backslash = matches!(c, ',' | '+' | '"' | '\\' | '<' | '>' | ';')
752	                || (at_edge && (c == ' ' || c == '#'));
753	            if needs_backslash {
754	                out.push('\\');
755	                out.push(c);
756	            } else if ('\0'..='\x1F').contains(&c) || c == '\x7F' {
757	                let mut buf = [0u8; 4];
758	                let b = c.encode_utf8(&mut buf).as_bytes()[0];
759	                write!(out, "\\{b:02X}").unwrap();
760	            } else {
761	                out.push(c);
762	            }
763	        }
764	        out
765	    }
766	
767	    fn format_time(tlv: Tlv) -> Result<String, String> {
768	        let (y, mo, d, h, mi, se) = match tlv.tag {
769	            TAG_UTC_TIME => {
770	                let c = tlv.content;
771	                if c.len() != 13 || c[12] != b'Z' {
772	                    return Err("UTCTime must be YYMMDDHHMMSSZ".to_string());
773	                }
774	                let digits = &c[..12];
775	                if !digits.iter().all(|b| b.is_ascii_digit()) {
776	                    return Err("non-numeric UTCTime".to_string());
777	                }
778	                let n = |a: usize, b: usize| -> u32 {
779	                    digits[a..=b].iter().fold(0, |acc, x| acc * 10 + (x - b'0') as u32)
780	                };
781	                let yy = n(0, 1);
782	                let year = if yy < 50 { 2000 + yy } else { 1900 + yy };
783	                (year as i32, n(2, 3), n(4, 5), n(6, 7), n(8, 9), n(10, 11))
784	            }
785	            TAG_GENERALIZED_TIME => {
786	                let c = tlv.content;
787	                if c.len() != 15 || c[14] != b'Z' {
788	                    return Err(
789	                        "GeneralizedTime must be YYYYMMDDHHMMSSZ in UTC".to_string()
790	                    );
791	                }
792	                let digits = &c[..14];
793	                if !digits.iter().all(|b| b.is_ascii_digit()) {
794	                    return Err("non-numeric GeneralizedTime".to_string());
795	                }
796	                let n = |a: usize, b: usize| -> u32 {
797	                    digits[a..=b].iter().fold(0, |acc, x| acc * 10 + (x - b'0') as u32)
798	                };
799	                (n(0, 3) as i32, n(4, 5), n(6, 7), n(8, 9), n(10, 11), n(12, 13))
800	            }
801	            other => return Err(format!("invalid time tag 0x{other:02X}")),
802	        };
803	        validate_datetime(y, mo, d, h, mi, se)?;
804	        Ok(format!("{y:04}-{mo:02}-{d:02}T{h:02}:{mi:02}:{se:02}Z"))
805	    }
806	
807	    fn validate_datetime(
808	        year: i32,
809	        month: u32,
810	        day: u32,
811	        hour: u32,
812	        minute: u32,
813	        second: u32,
814	    ) -> Result<(), String> {
815	        if !(1..=12).contains(&month) {
816	            return Err("invalid month in certificate time".to_string());
817	        }
818	        if hour > 23 || minute > 59 || second > 59 {
819	            return Err("invalid time of day in certificate time".to_string());
820	        }
821	        let leap = year % 4 == 0 && (year % 100 != 0 || year % 400 == 0);
822	        let days = [31, if leap { 29 } else { 28 }, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
823	        if day < 1 || day > days[(month - 1) as usize] {
824	            return Err("invalid day in certificate time".to_string());
825	        }
826	        Ok(())
827	    }
828	}
